	private void FixedUpdate()
	{
		ChaosStopwatch.Update(Time.time);
		Hazard.HandleGlobalTime();
		if (inGameScene)
		{
			HandleTimeUpdate(Time.fixedDeltaTime);
		}
	}

	private void Update()
