		{
			characterSelectUI.Activate();
		}
		if (queuedLevelName != string.Empty && curSkipLevelLoadFrame == 0)
		{
			LoadLevel(queuedLevelName);
		}
		else if (curSkipLevelLoadFrame > 0)
		{
			curSkipLevelLoadFrame--;
		}
		if (pauseQueued)
		{
			pauseQueued = false;
			GameUI.TogglePause();
			return;
		}
		if (loadingPauseQueued && !LoadingScreen.loading)
		{
			loadingPauseQueued = false;
			GameUI.TogglePause();
		}
		if ((!(levelSummary == null) && levelSummary.activated) || LoadingScreen.loading || !(currentLevelName != "Credits"))
