public static void LoadLevel(string givenLevelName)
{
	if (queuedLevelName == string.Empty)
	{
		curSkipLevelLoadFrame = skipLevelLoadFrames;
		queuedLevelName = givenLevelName;
		DisplayLoadingScreen(givenLevelName);
		players.Clear();
		ghosts.Clear();
		allies.Clear();
		enemies.Clear();
		bosses.Clear();
		previousPlayers.Clear();
		ClearLevelStats();
		if (itemSpawner != null)
		{
			itemSpawner.Reset();
		}
		return;
	}
	prevLevelName = Application.loadedLevelName;
	if (overlayEffects != null)
	{
		overlayEffects.anim.Play("Hidden");
	}
	NextLevelLoader.SetLevelInfo(givenLevelName);
	GameUI.dialogManager.Deactivate(resetDialog: true);
	GameUI.SetMoneyStatus(givenLevelName != "Tutorial" && givenLevelName != "Epilogue");
	PauseAllPlayers();
	GameDataManager.Save(updateCurrentData: true, prevLevelName == "PlayerRoom" || prevLevelName == "PvP");
	queuedLevelName = string.Empty;
	curSkipLevelLoadFrame = 0;
	SkillStoreItem.ResetSpawnedSkills();
	ItemStoreItem.ResetSpawnedItems();
	LootManager.Reset();
	if (resetCameraOnLoadLevel)
	{
		cameraController.vertMoveOnly = false;
		cameraController.horiMoveOnly = false;
		cameraController.overrideCameraUpdate = false;
		cameraController.disablePlayerTracking = false;
		cameraController.lockToSpawnPos = false;
	}
	Outfit.UpdateStarterOutfits(givenLevelName);
	pauseTimer = false;
	bool flag;
	Player[] array;
	switch (givenLevelName)
	{
	case "PlayerRoom":
		if (!(prevLevelName != "Hub"))
		{
			goto default;
		}
		goto case "InitialLoad";
	default:
		switch (givenLevelName)
		{
		case "Tutorial":
		case "PlayerRoomTutorial":
		case "Epilogue":
			break;
		default:
			goto IL_02aa;
		}
		goto case "InitialLoad";
	case "InitialLoad":
	case "TitleScreen":
		{
			Player[] array2 = activePlayers;
			foreach (Player player2 in array2)
			{
				Object.DestroyImmediate(player2.gameObject);
			}
			p1Joined = false;
			p2Joined = false;
			Level.isBossRushMode = false;
			Level.removeAllPits = false;
			Level.resetUsedRooms = true;
			HealStoreItem.healBuyCount = 0;
			SkillStoreItem.empoweredBuyCount = 0;
			if (Player.goldWallet != null)
			{
				Player.goldWallet.balance = 0;
			}
			HubEventHandler.cursePurchased = false;
			if (givenLevelName != "Epilogue")
			{
				stageCount = 0;
				tierCount = 0;
				loopCount = 0;
				NextLevelName = string.Empty;
				RunData.Reset();
			}
			EnemyGlobalStatManager.ResetScaling();
			resetHubVars = true;
			break;
		}
		IL_02aa:
		characterSelectUI.Disable();
		p1Joined = playerScripts[0] != null;
		p2Joined = playerScripts[1] != null;
		if (Globals.InGameScene(givenLevelName))
		{
			if (levelNameList.Contains(givenLevelName))
			{
				lastTierName = givenLevelName;
			}
			stageCount++;
			EnemyGlobalStatManager.CalculateScaling();
		}
		LootManager.SetCoopGoldMod = coopOn;
		flag = givenLevelName != "FinalBossLevel" && (givenLevelName.Contains("BossLevel") || givenLevelName.Contains("Ending"));
		if (flag)
		{
			cameraController.transform.position = Vector3.up;
			cameraController.VertMoveOnly = true;
		}
		array = activePlayers;
		foreach (Player player in array)
		{
			previousPlayers.Add(player);
			player.RegisterPlayer();
			if (flag)
			{
				player.myOrigin = Vector3.zero;
			}
			player.lastCheckpoint = Vector2.zero;
			if (player.health.healthStat.CurrentValue <= 0f)
			{
				if (coopOn)
				{
					player.ResetPlayer(originPosition: true, fullyRestoreHealth: false, resetState: true, resetOverdrive: true, 0.15f);
				}
				else
				{
					player.ResetPlayer(originPosition: true, fullyRestoreHealth: true, resetState: false);
				}
			}
			else
			{
				player.ResetPlayer(originPosition: true, fullyRestoreHealth: false, resetState: false);
			}
			player.Hide();
			if (prevLevelName != givenLevelName)
			{
				player.transform.position = Vector3.zero;
			}
			player.overheadPrompt.HidePrompt(string.Empty);
		}
		if (givenLevelName != "Hub")
		{
			resetHubVars = false;
			if (givenLevelName != "PlayerRoom")
			{
				RunData.InitRun();
			}
		}
		if (Globals.InGameScene(givenLevelName))
		{
			AchievementManager.UnlockAchievement(Achievement.StartCoopRun);
		}
		break;
	}
	if (givenLevelName == "Ending")
	{
		RunData.EndRun();
		if (totalTime < 1500f)
		{
			AchievementManager.UnlockAchievement(Achievement.SpeedRun, forceUnlock: true);
		}
		lastTotalTime = totalTime;
		RunHistoryEntry.Save();
	}
	Player[] array3 = activePlayers;
	foreach (Player player3 in array3)
	{
		if (player3 != null && player3.hurtBoxObj != null)
		{
			player3.hurtBoxObj.SetActive(value: true);
		}
	}
	if (levelLoadEventHandlers != null)
	{
		levelLoadEventHandlers(givenLevelName, prevLevelName);
	}
	currentLevelName = givenLevelName;
	Application.LoadLevel(givenLevelName);
}

private void OnLevelWasLoaded(int level)
{
	if (instance != null && instance != this)
	{
		return;
	}
	RenderSettings.ambientLight = GameDataManager.gameSettings.brightness * Color.white;
	inGameScene = Globals.InGameScene(Application.loadedLevelName);
	GameUI.RefreshCDUI();
	Player[] array = activePlayers;
	foreach (Player player in array)
	{
		player.fall.ignoreFall.RemoveMod("LevelLoad");
	}
	GameObject gameObject;
	if (cameraController != null)
	{
		gameObject = GameObject.Find("CameraSpawnArea");
		if (gameObject != null)
		{
			cameraController.transform.position = gameObject.transform.position;
		}
		else
		{
			cameraController.transform.position = cameraController.spawnPos;
		}
	}
	gameObject = GameObject.Find("StageLight");
	if (gameObject != null)
	{
		stageLight = gameObject.GetComponent<Light>();
	}
	gameObject = GameObject.Find("PlayerSpawnArea");
	if (gameObject != null)
	{
		Player[] array2 = activePlayers;
		foreach (Player player2 in array2)
		{
			player2.transform.position = gameObject.transform.position;
		}
	}
	if (NextLevelLoader.InTierScene(string.Empty))
	{
		StartCoroutine(LevelGenerator.Generate(this));
	}
	else if (Application.loadedLevelName == "TitleScreen")
	{
		loadingScreen.FadeOut();
	}
	else
	{
		StartCoroutine(WaitForDependiesToLoad());
	}
}

private IEnumerator WaitForDependiesToLoad()
{
	while (!coreDependenciesLoaded || !secondaryDependenciesLoaded || !effectsPoolsLoaded)
	{
		yield return null;
	}
	loadingScreen.FadeOut();
}

