private void HandleTimeUpdate(float givenDeltaTime)
{
	if (!pauseTimer)
	{
		levelTime += givenDeltaTime;
		totalTime += givenDeltaTime;
		timeSinceLastTimeSave += givenDeltaTime;
	}
}

