public static void ClearLevelStats(bool fullReset = false)
{
	Player[] array = activePlayers;
	foreach (Player player in array)
	{
		player.stats.ResetStats(fullReset);
	}
	levelGold = 0;
	levelPlat = 0;
	levelTime = 0f;
	if (fullReset)
	{
		totalGold = 0;
		totalPlat = 0;
		totalTime = 0f;
	}
}

private void InitData()
{
	StatManager.LoadPlayerSkills(string.Empty);
	StatManager.LoadEnemySkills(string.Empty);
	StatManager.LoadEnemySkills("FFA");
	StatManager.LoadEnemySkills("Only");
	StatManager.LoadEnemySkills("Scaled");
	StatManager.LoadEnemySkills("AsAlly");
}

private void InitEntityLists()
{
	if (playerScripts == null)
	{
		playerScripts = new Player[maxPlayerCount];
	}
	if (players == null)
	{
		players = new List<GameObject>();
	}
	if (ghosts == null)
	{
		ghosts = new List<GameObject>();
	}
	if (allies == null)
	{
		allies = new List<GameObject>();
	}
	if (enemies == null)
	{
		enemies = new List<GameObject>();
	}
	if (bosses == null)
	{
		bosses = new List<GameObject>();
	}
	if (previousPlayers == null)
	{
		previousPlayers = new List<Player>();
	}
}

private GameObject InstantiateIfNotPresent(string gameObjName, string resourcePath)
{
	GameObject gameObject = GameObject.Find(gameObjName);
	if (gameObject != null)
	{
		return gameObject;
	}
	GameObject original = ChaosBundle.Get(resourcePath);
	GameObject gameObject2 = Object.Instantiate(original);
	gameObject2.name = gameObjName;
	return gameObject2;
}

private T InstantiateIfNotPresent<T>(ref T objRef, string gameObjName, string resourcePath)
{
	if (objRef != null)
	{
		return objRef;
	}
	GameObject gameObject = InstantiateIfNotPresent(gameObjName, resourcePath);
	objRef = gameObject.GetComponent<T>();
	return objRef;
}

private void LoadCoreDependencies()
{
	if (!coreDependenciesLoaded)
	{
		InstantiateIfNotPresent(ref rewiredInput, "RewiredInput", "Assets/Prefabs/RewiredInput.prefab");
		InstantiateIfNotPresent(ref soundManager, "SoundManager", "Assets/Prefabs/SoundManager.prefab");
		InstantiateIfNotPresent("EventSystem", "Assets/Prefabs/UI/EventSystem.prefab");
		InstantiateIfNotPresent(ref mouseCursor, "MouseCursor", "Assets/Prefabs/UI/ChaosMouseCursor.prefab");
		InstantiateIfNotPresent("ConfirmHandlerUI", "Assets/Prefabs/UI/ConfirmHandlerUI.prefab");
		InstantiateIfNotPresent(ref gameUI, "GameUI", "Assets/Prefabs/UI/GameUI.prefab");
		optionsMenu = gameUI.transform.Find("OptionsMenu").GetComponent<OptionsMenu>();
		InstantiateIfNotPresent(ref loadingScreen, "LoadingScreen", "Assets/Prefabs/UI/LoadingScreen.prefab");
		InstantiateIfNotPresent(ref minimap, "MinimapCamera", "Assets/Prefabs/Environment/MinimapCamera.prefab");
		InstantiateIfNotPresent(ref minimapFullscreen, "MinimapFullscreenCamera", "Assets/Prefabs/Environment/MinimapFullscreenCamera.prefab");
		InstantiateIfNotPresent(ref runHistoryUI, "RunHistoryUI", "Assets/Prefabs/UI/RunHistoryUI.prefab");
		InstantiateIfNotPresent(ref logger, "Logger", "Assets/Prefabs/Logger.prefab");
		coreDependenciesLoaded = true;
	}
}

