using System.Collections.Generic;
using UnityEngine;

public static class PoolManager
{
	public static GenericDictionary pools = new GenericDictionary();

	public static Dictionary<Type, string> typeToPoolName = new Dictionary<Type, string>();

	private static Transform poolManagerTrans;

	private static Transform pEffectTrans;

	public static void CreatePool<T>(string prefabPath, int itemCount = 10, string poolName = "", bool silentlyFailDuplicate = true) where T : class
	{
		string empty = string.Empty;
		empty = ((!(poolName == string.Empty)) ? poolName : (prefabPath.Substring(prefabPath.LastIndexOf("/") + 1).Replace(".prefab", string.Empty) + "Pool"));
		if (pools.ContainsKey(empty))
		{
			if (!silentlyFailDuplicate)
			{
				Debug.Log("Error, attempt to create duplicate pool: " + empty);
			}
			return;
		}
		if (poolManagerTrans == null)
		{
			poolManagerTrans = new GameObject("PoolManagerPools").transform;
			UnityEngine.Object.DontDestroyOnLoad(poolManagerTrans.gameObject);
		}
		if (pEffectTrans == null)
		{
			pEffectTrans = new GameObject("ParticleEffectPools").transform;
			UnityEngine.Object.DontDestroyOnLoad(pEffectTrans.gameObject);
		}
		pools.Add(empty, new GenericPool<T>(prefabPath, itemCount, empty, dontDestroyOnLoad: true, (typeof(T) != typeof(ParticleEffect)) ? poolManagerTrans : pEffectTrans));
		typeToPoolName[typeof(T)] = empty;
	}

	public static T GetPoolItem<T>(string poolName) where T : class
	{
		if (!pools.ContainsKey(poolName))
		{
			if (!pools.ContainsKey(poolName + "Pool"))
			{
				Debug.Log("Error, pool doesn't exist: " + poolName);
				return (T)null;
			}
			poolName += "Pool";
		}
		return pools.GetValue<GenericPool<T>>(poolName).GetItem();
	}

	public static T GetPoolItem<T>() where T : class
	{
		string text = typeToPoolName[typeof(T)];
		if (!pools.ContainsKey(text))
		{
			Debug.Log("Error, pool doesn't exist: " + text);
			return (T)null;
		}
		return pools.GetValue<GenericPool<T>>(text).GetItem();
	}
